mapper.select:
select p.point_id as pointId, p.point_code as pointCode, p.point_name as pointName, p.slave_id as slaveId, p.addr_offset as addrOffset, p.unit as unit, count(s.sample_id) as sampleCount, min(s.value_scaled) as `minValue`, max(s.value_scaled) as `maxValue`, avg(s.value_scaled) as avgValue, max(s.read_time) as lastReadTime from meter_point p left join meter_sample s on s.point_id = p.point_id and s.read_time >= #{beginTime} and s.read_time <= #{endTime} where p.del_flag = '0' and p.status = '0'
and p.point_code = #{pointCode}
group by p.point_id, p.point_code, p.point_name, p.slave_id, p.addr_offset, p.unit having count(s.sample_id) > 0 order by p.sort_order asc, p.point_id asc
